# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">MEKKÎ VE MEDENÎ AYETLERİN KARŞILAŞTIRMALI ÖZELLİKLERİ</text>\n  <rect x="25" y="48" width="315" height="192" rx="10" fill="#dbeafe" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">Mekkî Ayetler (Hicretten Önce - 13 Yıl)</text>\n  <text x="40" y="98" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Konu:</tspan> İman esasları (tevhid, nübüvvet,</text>\n  <text x="48" y="115" font-size="11" fill="#1e3a8a">ahiret), şirkle mücadele ve temel ahlak</text>\n  <text x="40" y="138" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Kıssalar:</tspan> Geçmiş peygamber kıssalarıyla</text>\n  <text x="48" y="155" font-size="11" fill="#1e3a8a">Müslümanlara sabır ve teselli verilmesi</text>\n  <text x="40" y="178" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Üslup:</tspan> Kısa, veciz, edebî ve vurucu</text>\n  <text x="40" y="202" font-size="11.5" fill="#1e3a8a">• <tspan font-weight="bold">Hitap:</tspan> Genellikle "Ey insanlar!"</text>\n  <text x="48" y="219" font-size="11" font-weight="bold" fill="#1d4ed8">(Yâ eyyühe\'n-nâs) ve secde ayetleri</text>\n\n  <rect x="360" y="48" width="315" height="192" rx="10" fill="#dcfce7" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">Medenî Ayetler (Hicretten Sonra - 10 Yıl)</text>\n  <text x="375" y="98" font-size="11.5" fill="#14532d">• <tspan font-weight="bold">Konu:</tspan> İbadetler, muâmelât (aile, miras,</text>\n  <text x="383" y="115" font-size="11" fill="#14532d">ticaret, hukuk), cihat ve toplumsal düzen</text>\n  <text x="375" y="138" font-size="11.5" fill="#14532d">• <tspan font-weight="bold">Muhataplar:</tspan> Müslüman toplum, Ehl-i kitap</text>\n  <text x="383" y="155" font-size="11" fill="#14532d">(Yahudi ve Hristiyanlar) ve münafıklar</text>\n  <text x="375" y="178" font-size="11.5" fill="#14532d">• <tspan font-weight="bold">Üslup:</tspan> Uzun, açıklayıcı ve kural koyucu</text>\n  <text x="375" y="202" font-size="11.5" fill="#14532d">• <tspan font-weight="bold">Hitap:</tspan> Genellikle "Ey iman edenler!"</text>\n  <text x="383" y="219" font-size="11" font-weight="bold" fill="#15803d">(Yâ eyyühellezîne âmenû)</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">TEFSİR USULÜNDE MUHKEM-MÜTEŞÂBİH VE NÂSİH-MENSÛH</text>\n  <rect x="25" y="48" width="315" height="192" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">Muhkem ve Müteşâbih (Âl-i İmrân, 3/7)</text>\n  <rect x="40" y="85" width="285" height="65" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="182" y="105" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">Muhkem Ayetler (Ümmü\'l-Kitâb)</text>\n  <text x="182" y="123" text-anchor="middle" font-size="10.5" fill="#78350f">Anlamı açık ve kesin olan temel hükümler</text>\n  <text x="182" y="139" text-anchor="middle" font-size="10.5" fill="#78350f">(Tevhid, helal-haram, adalet, ibadet emirleri)</text>\n  <rect x="40" y="158" width="285" height="68" rx="6" fill="#ffffff" stroke="#f59e0b" stroke-width="1.5"/>\n  <text x="182" y="178" text-anchor="middle" font-size="12" font-weight="bold" fill="#b45309">Müteşâbih Ayetler</text>\n  <text x="182" y="196" text-anchor="middle" font-size="10.5" fill="#78350f">Çok anlamlı, mecazlı veya gaybî ifadeler</text>\n  <text x="182" y="212" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#92400e">İlke: Muhkem ayetler ışığında yorumlanır!</text>\n\n  <rect x="360" y="48" width="315" height="192" rx="10" fill="#f3e8ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">Nesih İlkesi (Nâsih ve Mensûh)</text>\n  <text x="375" y="98" font-size="11.5" fill="#581c87">• <tspan font-weight="bold">Tanım:</tspan> Önceki amelî bir hükmün daha</text>\n  <text x="383" y="115" font-size="11" fill="#581c87">sonra inen yeni bir ayetle değiştirilmesi</text>\n  <text x="375" y="138" font-size="11.5" fill="#581c87">• <tspan font-weight="bold">Mensûh:</tspan> Hükmü kaldırılan önceki ayet</text>\n  <text x="375" y="160" font-size="11.5" fill="#581c87">• <tspan font-weight="bold">Nâsih:</tspan> Yeni hükmü getiren sonraki ayet</text>\n  <text x="375" y="183" font-size="11.5" fill="#581c87">• <tspan font-weight="bold">Sınırı:</tspan> İnanç, ahlak ve haberlerde nesih</text>\n  <text x="383" y="200" font-size="11" fill="#581c87">olmaz; fer\'î/amelî hükümlerde uygulanır.</text>\n  <text x="375" y="220" font-size="11" font-weight="bold" fill="#6b21a8">• Örnek: Kıblenin Kâbe\'ye çevrilmesi</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">KUR\'AN\'I ANLAMADA BAĞLAM VE MAKÂSID (İLAHİ GAYELER)</text>\n  <rect x="25" y="50" width="315" height="190" rx="10" fill="#eff6ff" stroke="#3b82f6" stroke-width="2"/>\n  <text x="182" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">İki Boyutlu Bağlam İlkesi</text>\n  <rect x="40" y="88" width="285" height="62" rx="6" fill="#ffffff" stroke="#60a5fa" stroke-width="1.5"/>\n  <text x="182" y="108" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">1. Metin İçi Bağlam (Siyak - Sibak)</text>\n  <text x="182" y="126" text-anchor="middle" font-size="10.5" fill="#334155">Ayetin önceki (sibak) ve sonraki (siyak) ayetlerle</text>\n  <text x="182" y="142" text-anchor="middle" font-size="10.5" fill="#334155">ve Kur\'an\'ın konu bütünlüğüyle birlikte okunması</text>\n  <rect x="40" y="160" width="285" height="66" rx="6" fill="#ffffff" stroke="#60a5fa" stroke-width="1.5"/>\n  <text x="182" y="180" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e40af">2. Tarihsel Bağlam (Esbâb-ı Nüzûl)</text>\n  <text x="182" y="198" text-anchor="middle" font-size="10.5" fill="#334155">Ayetin iniş ortamı ve sebebi bilinerek</text>\n  <text x="182" y="214" text-anchor="middle" font-size="10.5" fill="#334155">evrensel mesajının günümüze taşınması</text>\n\n  <rect x="360" y="50" width="315" height="190" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="74" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Makâsıdü\'ş-Şerîa (Beş Temel Gaye)</text>\n  <text x="375" y="102" font-size="11.5" fill="#14532d">1. <tspan font-weight="bold">Hıfzu\'d-Dîn:</tspan> Dinin ve inancın korunması</text>\n  <text x="375" y="128" font-size="11.5" fill="#14532d">2. <tspan font-weight="bold">Hıfzu\'n-Nefs:</tspan> Can dokunulmazlığının korunması</text>\n  <text x="375" y="154" font-size="11.5" fill="#14532d">3. <tspan font-weight="bold">Hıfzu\'l-Akl:</tspan> Aklın ve iradenin korunması</text>\n  <text x="375" y="180" font-size="11.5" fill="#14532d">4. <tspan font-weight="bold">Hıfzu\'n-Nesl:</tspan> Neslin ve ailenin korunması</text>\n  <text x="375" y="206" font-size="11.5" fill="#14532d">5. <tspan font-weight="bold">Hıfzu\'l-Mâl:</tspan> Malın ve mülkiyetin korunması</text>\n  <text x="375" y="228" font-size="11" font-weight="bold" fill="#166534">• Adalet, rahmet, hikmet ve maslahat ilkesi</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
